import{z as d,x as m,o as n,c as X,q as i,j as l,D as o,d as e,s,S as p,b as t}from"./chunks/framework.C8m1ZpeB.js";const H=JSON.parse('{"title":"联合熵与互信息","description":"","frontmatter":{"title":"联合熵与互信息","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mutual-information.md","filePath":"cs/mutual-information.md","lastUpdated":1791413859000}'),E={name:"cs/mutual-information.md"};function h(A,a,Y,B,u,c){const r=m("Mermaid");return n(),X("div",null,[a[2]||(a[2]=i('<h1 id="联合熵与互信息" tabindex="-1">联合熵与互信息 <a class="header-anchor" href="#联合熵与互信息" aria-label="Permalink to &quot;联合熵与互信息&quot;">​</a></h1><div class="epigraph"><p>$X$ 与 $Y$ 共享多少信息，等于单独两份熵减去合在一起还剩下的不确定度。</p><footer>—— 据 Shannon, A Mathematical Theory of Communication, 1948 整理</footer></div><p>上一课<a href="/cs/entropy-bits">信息量与熵</a>钉死了自信息与 \\(H(X)\\)，并点名 \\(I(X;Y)=H(X)-H(X|Y)\\) 与容量式子，当时不展开。本课不重推 \\(-\\log p\\)，也不从信道框图另起综述。缺口是：<strong>两个</strong>随机变量怎么合在一张表上。没有联合熵，互信息只是一句定义，后课噪声信道没有「看见 \\(Y\\) 之后 \\(X\\) 还剩多少不确定」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(H(X)\\) 管一个源。存储、总线、后课纠错，都是「发出 \\(X\\)、收到 \\(Y\\)」。缺口因此不是更大的字母表，而是联合分布 \\(p(x,y)\\) 上的 \\(H(X,Y)\\)，以及链式法则 \\(H(X,Y)=H(X)+H(Y|X)\\)。互信息</p> \\[I(X;Y)=H(X)+H(Y)-H(X,Y)=H(X)-H(X|Y) \\]<p>对称，非负，当且仅当 \\(X\\perp Y\\) 时为零。上一课的「压缩下界」现在有了对照：相关的两路可以合起来压，独立则熵相加。</p><p>本课不证明 Shannon 第二定理，不把 \\(C=\\max I(X;Y)\\) 写成存在性论证。那是附录与信息论课，不插入主干。</p><h3 id="互信息不是「相关系数」" tabindex="-1">互信息不是「相关系数」 <a class="header-anchor" href="#互信息不是「相关系数」" aria-label="Permalink to &quot;互信息不是「相关系数」&quot;">​</a></h3><p>相关可以是非线性的：\\(I\\) 为零才叫独立（在有限字母表上）。只看 \\(\\mathrm{Cov}\\) 会漏异或一类依赖。也不把 \\(I(X;Y)\\) 当成语义上的「有用程度」：Shannon 不管意思。</p><p><span class="marginnote">常见误区：初学者容易以为「协方差为零就等于独立」。反例：\\(X\\) 等可能取 \\(-1,0,1\\)，\\(Y=X^2\\)，则 \\(E[XY]=0\\) 且 \\(E[X]=0\\)，协方差为零；可 \\(Y\\) 一眼就能判断 \\(X\\) 是否为零——相关系数没看见的依赖，互信息看得见。</span></p><p><span class="marginnote">Shannon 1948 用联合熵与条件熵写信道。维恩图式的 \\(H(X)\\)、\\(H(Y)\\)、\\(I(X;Y)\\) 是教学像，严格对象仍是联合分布上的和式。第一课的比特是符号位置；这里的比特仍是上一课的平均不确定度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有限 \\(\\mathcal{X},\\mathcal{Y}\\)，\\(p(x,y)\\gt 0\\) 的项才进对数。\\(H(Y|X)=\\sum_x p(x)H(Y|X=x)\\)。数据处理不等式点到为止：加工 \\(Y\\) 不能增加关于 \\(X\\) 的互信息——后课特征与哈希若当「无损」，须另证可逆。</p><p><span class="marginnote">数字实例：\\(X\\) 抛均匀硬币，信道以 0.9 概率如实传、0.1 概率翻转得 \\(Y\\)。则 \\(H(X)=1\\) 比特，\\(H(X|Y)=H(0.1)\\approx 0.469\\) 比特，于是 \\(I(X;Y)\\approx 0.531\\) 比特——看到 \\(Y\\) 后平均省下这么多「猜 \\(X\\)」的不确定。</span></p>',15)),(n(),l(p,null,{default:o(()=>[s(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20HX%5B%22H(X)%22%5D%20--%3E%20JOINT%5B%22H(X%2CY)%22%5D%0A%20%20HY%5B%22H(Y)%22%5D%20--%3E%20JOINT%0A%20%20JOINT%20--%3E%20I%5B%22I(X%3BY)%22%5D%0A%20%20I%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%86%97%E4%BD%99%E6%8D%A2%E6%88%90%E8%B7%9D%E7%A6%BB%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("离散概率公理仍在"),t("a",{href:"/cs/discrete-probability"},"更后的课"),e("才补全；本课继续用有限支撑上的 \\(p\\) 与期望。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"有了 \\(I(X;Y)\\)，噪声被写成「信道」：\\(Y\\) 是 \\(X\\) 的污染版本，\\(I\\) 给出平均还剩多少可分辨。下一课纠错不从熵再起，而从码字几何起：熵管速率下界，距离管最坏翻转。两套尺子从此分叉，本课只把联合这一侧钉死。",-1)),(n(),l(p,null,{default:o(()=>[s(r,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E6%BA%90%E7%AC%A6%E5%8F%B7%20X%22%5D%20--%3E%20CH%5B%22%E4%BF%A1%E9%81%93%3A%20%E8%A2%AB%E5%99%AA%E5%A3%B0%E6%B1%A1%E6%9F%93%22%5D%0A%20%20CH%20--%3E%20Y%5B%22%E6%94%B6%E5%88%B0%20Y%22%5D%0A%20%20Y%20--%3E%20F%5B%22%E5%8A%A0%E5%B7%A5%20f%22%5D%0A%20%20F%20--%3E%20Z%5B%22%E8%BE%93%E5%87%BA%20Z%22%5D%0A%20%20X%20-.-%3E%7C%22I(X%3BY)%22%7C%20Y%0A%20%20X%20-.-%3E%7C%22I(X%3BZ)%20%E5%8F%AA%E4%BC%9A%E6%9B%B4%E5%B0%8F%22%7C%20Z%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">直觉类比：把 \\(H(X)\\) 想成猜密码的平均难度，看到一条线索后剩下 \\(H(X|Y)\\)；省下的那块就是这条线索值多少互信息。线索越准省得越多，完全无关的线索一分不省，伪造的线索（重复加工）不会比原始线索更省。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入连续互信息、KL 散度全文、也不把大模型栏的注意力权重解释成 \\(I\\)。马尔可夫链 \\(X\\to Y\\to Z\\) 的数据处理只当一句话。</p><p>后课默认：谈到两路符号的共享信息，用 \\(I(X;Y)\\)；独立则互信息为零。检错要另加几何。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>联合熵满足链式法则；互信息是对称的共享不确定度。</li><li>\\(I=0\\) 当且仅当独立（有限字母表）。</li><li>压缩下界仍是熵；信道用互信息，纠错用距离，下一课换尺子。</li><li>出处：Shannon, <em>A Mathematical Theory of Communication</em>, 1948。</li></ul>',6))])}const I=d(E,[["render",h]]);export{H as __pageData,I as default};
